parameters.$filter:
cr40f_status eq 202410001 and createdon ge @{formatDateTime(
  addDays(
    startOfDay(
      convertFromUtc(
        utcNow(),
        'E. South America Standard Time'
      )
    ),
    -22
  ),
  'yyyy-MM-ddTHH:mm:ssZ'
)
}

Compose_DiasDesdeCriação.inputs:
@int(
  div(
    sub(
      ticks(startOfDay(convertFromUtc(utcNow(), 'E. South America Standard Time'))),
      ticks(startOfDay(convertFromUtc(items('Apply_to_each')?['createdon'], 'E. South America Standard Time')))
    ),
    864000000000
  )
)

Compose_Lembrete_Enviado_Hoje.inputs:
@if(
  empty(items('Apply_to_each')?['cr40f_datadoultimolembrete']),
  false,
  equals(
    formatDateTime(
      convertFromUtc(
        items('Apply_to_each')?['cr40f_datadoultimolembrete'],
        'E. South America Standard Time'
      ),
      'yyyy-MM-dd'
    ),
    formatDateTime(
      convertFromUtc(
        utcNow(),
        'E. South America Standard Time'
      ),
      'yyyy-MM-dd'
    )
  )
)
